type Config struct{BaseURL string `json:"base_url"`;TokenFile string `json:"token_file"`;Environment string `json:"environment_id"`;Pinned []string `json:"pinned_server_versions"`;Protocol int `json:"protocol"`;PageLimit int `json:"page_limit"`}
