func (Adapter) ParseConfig(b json.RawMessage)(any,error){return config(b)}
func get(ctx context.Context,c Config,path,cursor string,dst any,auth bool)error{budget:=int64(4<<20);return getBudget(ctx,c,path,cursor,dst,auth,&budget)}
