func allIndex(k string)string{_,v,_:=strings.Cut(k,"/thread:");return v}
type item struct{Completed string `json:"completedAt"`;Started string `json:"startedAt"`;Updated string `json:"updatedAt"`;Type string `json:"type"`;ID string `json:"id"`;RunID string `json:"runId"`;Text string `json:"text"`;Summary string `json:"summary"`;ToolName string `json:"toolName"`;Status string `json:"status"`;Streaming bool `json:"streaming"`;OutputOmitted bool `json:"outputOmitted"`;Input json.RawMessage `json:"input"`;Output json.RawMessage `json:"output"`;Attachments []json.RawMessage `json:"attachments"`;Child string `json:"childThreadId"`}
