type snapshot struct{Sequence int64 `json:"snapshotSequence"`;Cursor string `json:"historyCursor"`;Next string `json:"nextCursor"`;More bool `json:"hasMoreHistory"`;Budget bool `json:"payloadBudgetExceeded"`;Items []row `json:"items"`;Projection struct{Thread struct{Project string `json:"projectId"`;ID string `json:"id"`;Title string `json:"title"`;Branch string `json:"branch"`;CWD string `json:"worktreePath"`;Deleted *string `json:"deletedAt"`;Lineage struct{Parent string `json:"parentThreadId"`;Relation string `json:"relationshipToParent"`} `json:"lineage"`} `json:"thread"`;Providers []struct{Ref struct{Driver string `json:"driver"`;ID string `json:"nativeId"`;Strength string `json:"strength"`} `json:"nativeThreadRef"`} `json:"providerThreads"`;Rows []row `json:"visibleTurnItems"`;Runs []struct{ID string `json:"id"`;Status string `json:"status"`} `json:"runs"`} `json:"projection"`}
